    page("tools/","Visa and Passport Tools | Visa Radar","All Visa Radar tools in one place.","<h1>Tools</h1><div class='ledger'>"+"".join(f"<a class='row' href='{u}'><span>{t}</span><span class='mute'>{d}</span></a>" for u,t,d in T)+"</div>")
